// Why Code: parse do JSON do subagente + garantia de falha fechada (saida sempre no contrato)
const raw = String($json.output ?? '');
const fail = (m) => ({ json: { encontrado: false, logs: [], diagnostico: null, acao_sugerida: null, escalar: true, motivo_escalar: m } });
let o;
try { o = JSON.parse(raw.replace(/^```(?:json)?\s*|\s*```$/g, '')); } catch (e) { return [fail('falha ao consultar logs')]; }
if (typeof o !== 'object' || o === null || typeof o.encontrado !== 'boolean') return [fail('falha ao consultar logs')];
const logs = Array.isArray(o.logs) ? o.logs.slice(0, 5).map(l => ({ quando: l.quando, tipo: l.tipo, status: l.status, httpStatus: l.httpStatus, texto: typeof l.texto === 'string' ? l.texto.replace(/[\w.+-]+@[\w-]+(\.[\w-]+)+/g, '[email]') : l.texto })) : [];
return [{ json: { encontrado: o.encontrado, logs, diagnostico: o.diagnostico ?? null, acao_sugerida: o.acao_sugerida ?? null, escalar: o.escalar === true || (!o.encontrado && logs.length === 0 && o.escalar !== false), motivo_escalar: o.motivo_escalar ?? null } }];
